artifact.finding:
{
  "artifact_type": "Read-only finance and business planning assessment",
  "status": "Review completed; no order was created or submitted.",
  "request_context": {
    "request": "Place an additional order for strawberry concentrate.",
    "purpose": "Assess budget availability, cost-center assignment, financial approval, and spending controls for MAT-STRAW-01.",
    "material_id": "MAT-STRAW-01",
    "context_id": "CTX-RM-STRAWBERRY"
  },
  "assessment": {
    "financial_readiness": "Not established from the available evidence.",
    "budget_availability": "No approved budget evidence was found.",
    "cost_center_assignment": "No cost-center record was found.",
    "financial_approval": "Required but not evidenced as completed.",
    "spending_control": "DEMO-FC-101 is Pending and states that approval is required above USD 3,000."
  },
  "verified_facts": [
    {
      "source_id": "DEMO-ST-101",
      "fact": "Current stock is 420 kg."
    },
    {
      "source_id": "DEMO-PP-101",
      "fact": "Planned requirement is 1,200 kg, producing a 780 kg replenishment gap."
    },
    {
      "source_id": "DEMO-PR-101",
      "fact": "The procurement record is Draft and quotes 800 kg at USD 4.80 per kg."
    },
    {
      "source_id": "DEMO-PR-101",
      "fact": "The draft quotation value is USD 3,840, calculated as 800 kg multiplied by USD 4.80 per kg."
    },
    {
      "source_id": "DEMO-FC-101",
      "fact": "The financial-control estimate is USD 3,744 for 780 kg, with status Pending."
    },
    {
      "source_id": "DEMO-FC-101",
      "fact": "Both the USD 3,744 estimate and the USD 3,840 quotation exceed the USD 3,000 approval threshold."
    }
  ],
  "calculations": [
    {
      "description": "Replenishment gap",
      "calculation": "1,200 kg - 420 kg",
      "result": "780 kg"
    },
    {
      "description": "Draft quotation value",
      "calculation": "800 kg x USD 4.80 per kg",
      "result": "USD 3,840"
    },
    {
      "description": "Quoted quantity above documented gap",
      "calculation": "800 kg - 780 kg",
      "result": "20 kg"
    },
    {
      "description": "Difference between draft quotation and financial-control estimate",
      "calculation": "USD 3,840 - USD 3,744",
      "result": "USD 96"
    }
  ],
  "missing_inputs": [
    "Approved budget availability",
    "Assigned cost center",
    "Required financial approval and approval status",
    "Confirmed order quantity",
    "Supplier identity and delivery location",
    "Lead time and required delivery date",
    "Open purchase orders and inbound deliveries",
    "Freight, taxes, duties, insurance, Incoterms, payment terms, and other landed-cost assumptions",
    "Basis for the USD 96 difference between the quotation and the financial-control estimate",
    "Confirmation that the quotation remains valid on the intended order date"
  ],
  "prior_findings": [
    {
      "source": "fb-procurement-team",
      "record_ids": [
        "DEMO-PR-101",
        "DEMO-ST-101"
      ],
      "finding": "The quotation broadly covers the documented replenishment gap, but the requested quantity, delivery details, open orders, approvals, and purchasing terms remain unconfirmed."
    },
    {
      "source": "manufacturing-planning-team",
      "record_ids": [
        "DEMO-PP-101",
        "DEMO-MI-101",
        "DEMO-PR-101"
      ],
      "finding": "Additional supply is supported by the planned requirement and stock position, but timing is not validated because the production delivery date is pending."
    }
  ],
  "profitability_review": {
    "scenario_status": "No profitability scenarios were returned for CTX-RM-STRAWBERRY.",
    "conclusion": "No profitability or approved-spend conclusion can be established."
  },
  "team_conclusion": "Read-only evidence supports a potential replenishment need, but it does not establish budget availability, cost-center authorization, completed financial approval, or spending authorization. The proposed 800 kg quantity is 20 kg above the documented gap, and the draft quotation is not an approved order value.",
  "next_review": [
    "Obtain documented budget and cost-center authorization.",
    "Complete and document the approval required above USD 3,000.",
    "Confirm the order quantity, delivery date, supplier, and delivery location.",
    "Reconcile the USD 3,840 quotation with the USD 3,744 control estimate.",
    "Confirm open orders and inbound deliveries and complete the landed-cost review."
  ],
  "read_only_statement": "No purchase, approval, submission, or data change occurred."
}

